  local description="$1"; shift
  if "$@"; then"""),
("""    thyrox_ok "$1"
  else
    thyrox_fail "$1 (sonda""","""    thyrox_ok "$description"
  else
    thyrox_fail "$description (sonda"""),
("""DAEMON_PID=$$
""","""probe_launched() {
  [[ $PROBE_RC -eq 0 && "$(probe_field result)" == launched ]]
}

probe_retired_container() {
  [[ $PROBE_RC -eq 0 && "$(probe_field removed)" == true ]]
}

# La sonda salio con el codigo $1 y publico el error de nombre $2.
probe_failed_with() {
  [[ $PROBE_RC -eq $1 && "$(probe_field error)" == "$2" ]]
}

probe_failed_at_stage() {
  [[ "$(probe_field stage)" == "$1" ]]
}

container_absent() {
  ! container_exists "$1"
}

orphan_launched() {
  probe_launched && container_exists "$1"
}

probe_reports_retired() {
  [[ $PROBE_RC -eq 0 ]] && printf '%s\\n' "$PROBE_OUT" | grep -qx "retired=thyrox-worker-$1"
}

DAEMON_PID=$$
"""),
]
for a,b in rep:
    assert s.count(a)==1,a; s=s.replace(a,b)
s=s.replace("""# `--pull=never` hace que la ausencia se resuelva en local, sin red.
""","""# El prefijo `localhost/` resuelve la ausencia sin tocar un registro externo.
""")
s=s.replace(' \\\n  --resource-arg=--pull=never -- /bin/helper',' \\\n  -- /bin/helper')
subs=[
(r"""check "(caso 1: launch[^"]*)" \\\n  '[^']*'""", r'check "\1" probe_launched'),
(r"""'container_exists "\$CPU_WORKER"'""", 'container_exists "$CPU_WORKER"'),
(r"""'process_alive "\$CPU_PID"'""", 'process_alive "$CPU_PID"'),
(r"""check "(caso 2: retire sale[^"]*)" \\\n  '[^']*'""", r'check "\1" probe_retired_container'),
(r"""'! container_exists "\$(\w+)"'""", r'container_absent "$\1"'),
(r"""'process_exits_within_deadline "\$(\w+)"'""", r'process_exits_within_deadline "$\1"'),
(r"""check "(caso [34]: [^"]*WorkerLaunchError)" \\\n  '[^']*'""", r'check "\1" probe_failed_with "$LAUNCH_FAILURE_EXIT_CODE" WorkerLaunchError'),
(r"""'\[\[ "\$\(probe_field stage\)" == (\w+) \]\]'""", r'probe_failed_at_stage \1'),
(r"""check "(caso 5: el huerfano existe[^"]*)" \\\n  '[^']*'""", r'check "\1" orphan_launched "$ORPHAN_WORKER"'),
(r"""check "(caso 5: reconcileOrphans[^"]*)" \\\n  '[^']*'""", r'check "\1" probe_reports_retired "$ORPHAN_WORKER"'),
(r"""check "(caso 6: CUDA[^"]*)" \\\n  '[^']*'""", r'check "\1" probe_failed_with "$UNSUPPORTED_EXIT_CODE" UnsupportedAcceleratorError'),
]
for a,b in subs:
    s,n=re.subn(a,b,s); assert n>=1,(a,n)
open(p,'w').write(s)
